def cut(name, start_marker, end_marker, replacement=""):
    p = pathlib.Path(name)
    s = p.read_bytes().decode("utf-8")
    crlf = "\r\n" in s
    s = s.replace("\r\n", "\n")
    start = s.index(start_marker)
    end = s.index(end_marker, start)
    s = s[:start] + replacement + s[end:]
    if crlf:
        s = s.replace("\n", "\r\n")
    p.write_bytes(s.encode("utf-8"))

