import json, re, sys, collections

def load(path):
    d = json.load(open(path, encoding="utf-8"))
    items = d.get("settingItems", [])
    cases = d["cases"]
    for req in cases.values():
        for a in req["answers"]:
            out = json.loads(a["output"])
            if a.pop("settingItems", False):
                for f in ("items", "unknownKeys"):
                    if f in out["result"]:
                        out["result"][f] = [items[i] for i in out["result"][f]]
            if a.pop("sharedWorkspace", False):
                out.update(req["sharedWorkspace"])
            a["output"] = out
    return cases

VOLATILE = re.compile(r'("(?:updatedAt|createdAt|timestamp|at|time|savedAt|modifiedAt|startedAt|finishedAt)"\s*:\s*")[^"]*(")')

def norm(v):
    s = json.dumps(v, sort_keys=True, ensure_ascii=False)
    s = VOLATILE.sub(r"\1T\2", s)
    s = re.sub(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?Z?", "T", s)
    s = re.sub(r'"(sessionId|expectedSessionId|revision|expectedRevision|actionId|handle|call_id|id|plateId|objectId|attachmentId|seq)"\s*:\s*("[^"]*"|\d+)', r'"\1":X', s)
    s = re.sub(r"jusprin-shell-[0-9a-f-]+", "TMP", s)
    s = re.sub(r"\\\\u[0-9a-f]{4}", "", s)
    return s

old, new = load(sys.argv[1]), load(sys.argv[2])
for name in new:
    o, n = old[name], new[name]
    ot = collections.Counter(a["tool"] for a in o["answers"])
    nt = collections.Counter(a["tool"] for a in n["answers"])
    diff_tools = {k: (ot.get(k, 0), nt.get(k, 0)) for k in set(ot) | set(nt) if ot.get(k, 0) != nt.get(k, 0)}
    oi, ni = o["body"]["input"], n["body"]["input"]
    changed_items = [i for i in range(min(len(oi), len(ni))) if norm(oi[i]) != norm(ni[i])]
    print(f"{name}: input {len(oi)}->{len(ni)}, changed items {changed_items[:8]}, answers {len(o['answers'])}->{len(n['answers'])} {diff_tools or ''}")
    if "-v" in sys.argv:
        for i in changed_items[:3]:
            a, b = norm(oi[i]), norm(ni[i])
            j = next((k for k in range(min(len(a), len(b))) if a[k] != b[k]), min(len(a), len(b)))
            print("   ", i, "OLD", a[max(0, j - 150):j + 250])
            print("   ", i, "NEW", b[max(0, j - 150):j + 250])

